// Parsa i 3 feed iCal e produce un array di prenotazioni

function parseIcal(raw, aptId) {
  const bookings = [];
  const events = raw.split('BEGIN:VEVENT');
  events.shift(); // rimuove l'header

  events.forEach((evt, idx) => {
    const get = (field) => {
      const match = evt.match(new RegExp(field + '[^:]*:([^\r\n]+)'));
      return match ? match[1].trim() : '';
    };

    const dtstart = get('DTSTART');
    const dtend   = get('DTEND');
    const summary = get('SUMMARY') || 'Ospite';

    if (!dtstart || !dtend) return;

    // Converte YYYYMMDD o YYYYMMDDTHHmmssZ in YYYY-MM-DD
    const toDate = (s) => {
      const d = s.replace(/T.*/, '').replace(/Z$/, '');
      return d.slice(0,4) + '-' + d.slice(4,6) + '-' + d.slice(6,8);
    };

    // iCal: SUMMARY di solito è il nome ospite o "CLOSED" per blocchi
    // Ignora blocchi generici
    const summaryClean = summary.replace(/\\n/g,' ').replace(/\\,/g,',').trim();
    if (['CLOSED','BLOCKED','NOT AVAILABLE','Airbnb (Not available)'].includes(summaryClean.toUpperCase())) return;

    bookings.push({
      id: aptId * 1000 + idx,
      aptId,
      guest: summaryClean,
      checkin:  toDate(dtstart),
      checkout: toDate(dtend),
      price: '',
      channel: 'Krossbooking'
    });
  });

  return bookings;
}

