const rawMarika = items[1].json.data || items[1].json.body || Object.values(items[1].json)[0] || '';
const rawTone   = items[2].json.data || items[2].json.body || Object.values(items[2].json)[0] || '';

const all = [
  ...parseIcal(String(rawMattia), 1),
  ...parseIcal(String(rawMarika), 2),
  ...parseIcal(String(rawTone),   3),
];

return [{ json: { bookings: all } }];

